with setting as materialized (select pg_catalog.set_config('search_path','',true))
select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('finance','api','ops','telegram_private') and c.relkind in ('r','p','v')),
 'columns',(select jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname in ('finance','api','ops','telegram_private') and c.relkind in ('r','p','v') and a.attnum>0 and not a.attisdropped),
 'constraints',(select jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'name',k.conname,'def',pg_get_constraintdef(k.oid)) order by n.nspname,c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('finance','api','ops','telegram_private')),
 'indexes',(select jsonb_agg(jsonb_build_object('table',schemaname||'.'||tablename,'name',indexname,'def',indexdef) order by schemaname,tablename,indexname) from pg_indexes where schemaname in ('finance','api','ops','telegram_private')),
 'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'hash',md5(replace(pg_get_functiondef(p.oid),E'\r\n',E'\n'))) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('finance','api','ops','telegram_private')),
 'triggers',(select jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'name',t.tgname,'def',pg_get_triggerdef(t.oid)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('finance','api','ops','telegram_private')),
 'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in ('finance','api','ops','telegram_private') or (schemaname='storage' and policyname like 'category_images%')),
 'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'super',rolsuper,'bypass',rolbypassrls,'inherit',rolinherit,'create_role',rolcreaterole,'create_db',rolcreatedb,'login',rolcanlogin) order by rolname) from pg_roles where rolname in ('app_executor','finzi_deletion_worker','finzi_telegram_gateway')),
 'memberships',(select jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'admin',a.admin_option,'inherit',a.inherit_option,'set',a.set_option) order by r.rolname,m.rolname) from pg_auth_members a join pg_roles r on r.oid=a.roleid join pg_roles m on m.oid=a.member where r.rolname in ('app_executor','finzi_deletion_worker','finzi_telegram_gateway') or m.rolname in ('app_executor','finzi_deletion_worker','finzi_telegram_gateway')),
 'extensions',(select jsonb_agg(extname order by extname) from pg_extension),
 'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'size',file_size_limit,'mime',allowed_mime_types) order by id) from storage.buckets)
) as catalog from setting;
